/* Shared size controls for every scene tool and visible panel. */
(()=>{const T=AFRAME.THREE;
AFRAME.registerComponent('object-size',{
 init(){this.key='scene';this.records=new Map();this.positions=new Map();this.listeners=[];const dock=document.getElementById('spatialDock');this.buttons=[];for(const [label,action] of [['Size: Globe',()=>this.cycle()],['Object −',()=>this.step(-1)],['Object +',()=>this.step(1)],['Reset size',()=>this.reset()],['Nearer',()=>this.moveDepth(1)],['Farther',()=>this.moveDepth(-1)],['Reset distance',()=>this.resetDistance()]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.hidden=label==='Reset size'||label==='Reset distance';b.onclick=action;dock.append(b);this.buttons.push(b)}window.globiquest.objectSizer=this;window.globiquest.resizeSelectedObject=direction=>this.step(direction);const on=(el,name,fn,options)=>{el?.addEventListener(name,fn,options);this.listeners.push(()=>el?.removeEventListener(name,fn,options))};on(window,'wheel',e=>{if(e.target!==this.el.canvas||window.globiquest.travelEditing)return;this.pick(e);this.step(e.deltaY<0?1:-1);e.preventDefault();e.stopImmediatePropagation()},{capture:true,passive:false});on(window,'keydown',e=>{if(window.globiquest.travelEditing||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||e.repeat)return;if(['Equal','NumpadAdd','Minus','NumpadSubtract'].includes(e.code)){this.step(['Equal','NumpadAdd'].includes(e.code)?1:-1);e.preventDefault()}});for(const id of ['leftHand','rightHand'])for(const event of ['abuttondown','xbuttondown'])on(document.getElementById(id),event,()=>this.cycle());this.mouseButtons=[];this.update()},
 visible(object){if(!object)return false;for(let o=object;o;o=o.parent)if(!o.visible)return false;return !!object.parent},
 targets(){const out=[],add=(key,label,el,object=el?.object3D)=>{if(this.visible(object))out.push({key,label,el,object})};const sceneWorld=this.el.components?.['xr-view']?.world;if(sceneWorld)add('scene','Tiny world',null,sceneWorld);for(const [key,label,id] of [['globe','Globe','mapRoot'],['island','Tiny world','environment'],['telescope','Telescope','celestialTelescope'],['lens','Lens','lens'],['tutor','Tutor','nova'],['navigation','Navigation','nav'],['explore','Explore panel','regions'],['words','Words panel','vocabulary'],['guide','Guide panel','guideControls'],['music','Music panel','musicControls'],['lens-panel','Lens panel','toolControls'],['art','Art studio','featureWorkspace'],['destination','Destination','destination'],['celestial','Celestial panel','scopeView'],['guitar-panel','Guitar controls','guitarCornerControls'],['parachutes','Parachute controls','parachuteHUD'],['feature-island','Art island','featureIsland']])add(key,label,document.getElementById(id));for(const [key,label,selector] of [['guitar','Guitar','[musical-guitar]'],['travel','Travel panel','[travel-console]']])add(key,label,document.querySelector(selector));if(window.globiquest.artPlay?.items.length)add('art-keepsakes','3D art',null,window.globiquest.artPlay.root);const patch=window.globiquest.globePatch;if(patch?.root?.visible)add('miniature','Pulled miniature',null,patch.model);return out},
 current(){const targets=this.targets();return targets.find(t=>t.key===this.key)||targets[0]},
 cycle(){this.depthStatus='';const targets=this.targets();if(!targets.length)return;const index=targets.findIndex(t=>t.key===this.key);this.key=targets[(index+1)%targets.length].key;this.update();this.refresh();if(typeof notify==='function')notify('Size target: '+this.current().label+' · Object − / + to resize.')},
 record(target){let record=this.records.get(target.key);if(!record||record.object!==target.object){record={...target,base:target.object.scale.clone(),scale:target.object.scale.clone(),factor:1};this.records.set(target.key,record)}return record},
 step(direction){const target=this.current();if(!target)return;this.key=target.key;if(target.key==='scene'){window.globiquest.sceneZoom?.(direction*.15)}else if(target.key==='lens'&&window.globiquest.magicLens){window.globiquest.magicLens.zoom(direction*.5)}else if(target.key==='globe'){window.globiquest.resizeGlobe?.(direction*.12)}else{const r=this.record(target);r.factor=T.MathUtils.clamp(r.factor*(direction>0?1.15:1/1.15),target.key==='navigation'?.7:.45,target.key==='navigation'?1.25:2.2);r.scale.copy(r.base).multiplyScalar(r.factor);target.object.scale.copy(r.scale);target.el?.setAttribute('scale',{x:r.scale.x,y:r.scale.y,z:r.scale.z});if(target.el?.id==='lens')target.el.dataset.userPlaced='true';const dragger=target.el?.components?.['xr-nav-drag'];if(dragger?.pose)dragger.pose.scale.copy(target.object.getWorldScale(new T.Vector3()));target.object.updateWorldMatrix(true,true)}this.update();this.refresh()},
 reset(){const target=this.current();if(!target)return;if(target.key==='scene')window.globiquest.resetSceneZoom?.();else if(target.key==='lens'&&window.globiquest.magicLens)window.globiquest.magicLens.zoomTo(2);else if(target.key==='globe')window.globiquest.resetGlobeSize?.();else{const r=this.records.get(target.key);if(r&&r.object===target.object){target.object.scale.copy(r.base);target.el?.setAttribute('scale',{x:r.base.x,y:r.base.y,z:r.base.z});const d=target.el?.components?.['xr-nav-drag'];if(d?.pose)d.pose.scale.copy(target.object.getWorldScale(new T.Vector3()));this.records.delete(target.key)}}this.update();this.refresh()},
 depthInfo(target=this.current()){
  if(!target?.object.parent)return null;const object=target.object;object.updateWorldMatrix(true,true);const pose=window.globiquest.xrHeadPose?.(),head=pose?.position||this.el.camera.getWorldPosition(new T.Vector3()),panel=!!target.el?.components?.['xr-nav-drag'],globe=['scene','globe'].includes(target.key)?document.getElementById('mapRoot')?.object3D:null;
  // A panel's width is not its depth: a bounding sphere can prohibit all forward movement.
  const bounds=new T.Box3().setFromObject(object),center=globe?globe.getWorldPosition(new T.Vector3()):panel||bounds.isEmpty()?object.getWorldPosition(new T.Vector3()):bounds.getCenter(new T.Vector3()),distance=center.distanceTo(head),radius=globe?1.2*globe.getWorldScale(new T.Vector3()).x:panel?0:bounds.isEmpty()?0:bounds.getBoundingSphere(new T.Sphere()).radius;
  return {head,center,distance,minimum:panel?1.1:Math.max(.45,radius+.2),forward:pose?.forward||this.el.camera.getWorldDirection(new T.Vector3())};
 },
 distanceLabel(){const info=this.depthInfo();return info?info.distance.toFixed(2)+' m':''},
 moveDepth(direction){const target=this.current(),info=this.depthInfo(target);if(!info)return;this.key=target.key;const object=target.object,parent=object.parent,{head,center,distance,minimum,forward}=info,step=.3,amount=direction>0?Math.min(step,Math.max(0,distance-minimum)):-Math.min(step,Math.max(0,15-distance));
  if(Math.abs(amount)<.001){this.depthStatus=direction>0?'Nearest position reached':'Farthest position reached';this.refresh();if(typeof notify==='function')notify(this.depthStatus+' · '+target.label+' · '+this.distanceLabel());return}
  let record=this.positions.get(target.key);if(!record||record.object!==object){record={...target,home:object.position.clone(),position:object.position.clone(),offset:target.key==='scene'?this.el.components['xr-view'].depthOffset?.clone()||new T.Vector3():null};this.positions.set(target.key,record)}
  target.el?.components?.['bimanual-globe']?.releaseAll?.();const before=object.position.clone(),axis=distance>.001?head.clone().sub(center).normalize():forward.clone().negate(),world=object.getWorldPosition(new T.Vector3()).addScaledVector(axis,amount);parent.updateWorldMatrix(true,false);object.position.copy(parent.worldToLocal(world));record.position.copy(object.position);
  if(target.key==='scene'){const view=this.el.components['xr-view'];view.depthOffset ||= new T.Vector3();view.depthOffset.add(object.position.clone().sub(before));view.applyWorldTransform?.()}
  if(target.el){target.el.setAttribute('position',{x:object.position.x,y:object.position.y,z:object.position.z});target.el.dataset.panelManual='true';target.el.dataset.userPlaced='true';const globe=target.el.components?.['bimanual-globe'];if(globe)globe.placed=true;object.updateWorldMatrix(true,true);const d=target.el.components?.['xr-nav-drag'];if(d)d.pose={position:object.getWorldPosition(new T.Vector3()),quaternion:object.getWorldQuaternion(new T.Quaternion()),scale:object.getWorldScale(new T.Vector3())};if(target.el.id==='nav')this.el.components['xr-view'].navManual=true}
  object.updateWorldMatrix(true,true);this.depthStatus='';this.refresh();if(typeof notify==='function')notify(target.label+' · '+this.distanceLabel()+' · '+(direction>0?'moved nearer':'moved farther'));return Math.abs(amount);
 },
 resetDistance(){const target=this.current(),r=target&&this.positions.get(target.key);if(!r)return;if(target.key==='scene'){const view=this.el.components['xr-view'];view.depthOffset.copy(r.offset);view.setZoom(view.zoom)}else{r.object.position.copy(r.home);r.el?.setAttribute('position',{x:r.home.x,y:r.home.y,z:r.home.z});const d=r.el?.components?.['xr-nav-drag'];if(d?.pose)d.pose.position.copy(r.object.getWorldPosition(new T.Vector3()))}this.positions.delete(target.key);this.refresh()},
 forget(el){for(const [key,r] of this.records)if(r.el===el)this.records.delete(key)},
 update(){const target=this.current();if(!target)return;this.key=target.key;const r=this.records.get(target.key),percent=target.key==='scene'?Math.round((this.el.components?.['xr-view']?.zoom||1)*100):target.key==='globe'?Math.round((window.globiquest.getGlobeScale?.()||1)*100):Math.round((r?.factor||1)*100);this.buttons[0].textContent='Size: '+target.label;this.buttons[3].textContent=target.key==='lens'&&window.globiquest.magicLens?'Reset magnifier · '+window.globiquest.state.zoom+'×':'Reset size · '+percent+'%'},
 valueLabel(){const t=this.current();if(!t)return '';if(t.key==='scene')return Math.round((this.el.components?.['xr-view']?.zoom||1)*100)+'%';if(t.key==='globe')return Math.round((window.globiquest.getGlobeScale?.()||1)*100)+'%';if(t.key==='lens'&&window.globiquest.magicLens)return window.globiquest.state.zoom+'×';return Math.round((this.records.get(t.key)?.factor||1)*100)+'%'},
 refresh(){if(this.el.is('vr-mode'))window.globiquest.renderXRNav?.(document.getElementById('nav'))},
 pick(e){const bounds=this.el.canvas.getBoundingClientRect(),caster=new T.Raycaster();caster.setFromCamera(new T.Vector2((e.clientX-bounds.left)/bounds.width*2-1,-(e.clientY-bounds.top)/bounds.height*2+1),(window.globiquest.xrPointerCamera?.()||this.el.camera));let best;for(const target of this.targets()){target.object.updateWorldMatrix(true,true);const hit=caster.intersectObject(target.object,true)[0];if(hit&&(!best||hit.distance<best.distance-1e-5||Math.abs(hit.distance-best.distance)<1e-5&&(()=>{for(let p=target.object.parent;p;p=p.parent)if(p===best.object)return true;return false})()))best={...target,distance:hit.distance}}if(best)this.key=best.key},
 tick(time){for(const [key,r] of this.positions){if(!r.object.parent||r.el?.isConnected===false){this.positions.delete(key);continue}if(key==='scene'){this.el.components['xr-view']?.applyWorldTransform?.();continue;}const d=r.el?.components?.['xr-nav-drag'],manager=document.getElementById('earthRoot')?.components?.['globe-rotation'],grabs=r.el?.components?.['bimanual-globe']?.grabs;if(d?.source||manager?.moving?.object3D===r.object||grabs?.size)r.position.copy(r.object.position);else r.object.position.copy(r.position)}for(const [key,r] of this.records){if(!r.object.parent||r.el?.isConnected===false){this.records.delete(key);continue}r.object.scale.copy(r.scale)}if(time-(this.lastUpdate||0)<500)return;this.lastUpdate=time;const old=this.buttons[0].textContent;this.update();if(old!==this.buttons[0].textContent)this.refresh()},
 remove(){this.listeners.forEach(fn=>fn());this.buttons.forEach(b=>b.remove());this.mouseButtons?.forEach(b=>b.remove());this.records.clear();this.positions.clear();delete window.globiquest.objectSizer;delete window.globiquest.resizeSelectedObject}
});const setup=()=>scene.setAttribute('object-size','');if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});})();
